const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

// Simple readability-like extraction
function extractContent(html) {
  if (!html) return { title: '', content: '', excerpt: '', byline: '', length: 0 };

  // Remove scripts, styles, and comments
  let clean = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '');

  // Extract title
  const titleMatch = clean.match(/<title[^>]*>([^<]*)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : '';

  // Try to find main content
  let content = '';

  // Look for article or main content areas
  const articleMatch = clean.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
  const mainMatch = clean.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
  const contentMatch = clean.match(/<div[^>]*(?:class|id)=["'][^"']*(?:content|article|post|entry)[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);

  if (articleMatch) {
    content = articleMatch[1];
  } else if (mainMatch) {
    content = mainMatch[1];
  } else if (contentMatch) {
    content = contentMatch[1];
  } else {
    // Fallback: get body content
    const bodyMatch = clean.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    content = bodyMatch ? bodyMatch[1] : clean;
  }

  // Remove remaining HTML tags and clean up
  const textContent = content
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  // Extract author/byline
  let byline = '';
  const bylineMatch = clean.match(/<[^>]*(?:class|rel)=["'][^"']*(?:author|byline)[^"']*["'][^>]*>([^<]*)</i);
  if (bylineMatch) byline = bylineMatch[1].trim();

  return {
    title: title,
    content: textContent,
    excerpt: textContent.substring(0, 200) + (textContent.length > 200 ? '...' : ''),
    byline: byline,
    length: textContent.length,
    text_direction: 'ltr'
  };
}

const results = items.map(item => {
  const fetchTime = Date.now() - startTime;

  // Check for errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.statusCode || 500,
          message: item.json.error.message || 'Failed to fetch URL',
          status: 'FETCH_ERROR'
        },
        data: null,
        meta: {
          provider: 'web-scraper',
          search_performed: false,
          sources_count: 0
        },
        usage: null
      }
    };    
  };
  }

  const statusCode = item.json.statusCode || 200;
  const html = item.json.body || '';
  const finalUrl = item.json.headers?.location || webhookData.body.url;

  // Check status code
  if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: `HTTP ${statusCode} error`,
        status: 'HTTP_ERROR'
      },
      data: null,
      meta: {
        provider: 'web-scraper',
        search_performed: false,
        sources_count: 0
      },
      usage: null
    }
  };  
  }

  const extractStart = Date.now();
  const extracted = webhookData.body.options?.extract_content !== false ? extractContent(html) : null;
  const extractTime = Date.now() - extractStart;  
  const urlObj = new URL(webhookData.body.url);
  const domain = urlObj.hostname;

  return {
    json: {
      success: true,
      data: {
        query: webhookData.body.url,
        content: extracted ? extracted.content : '',
        sources: [{
          title: extracted ? extracted.title : '',
          url: webhookData.body.url,
          domain: domain
        }]
      },
      meta: {
        provider: 'web-scraper',
        search_performed: false,
        sources_count: 1,
        // Keep detailed info in _debug for troubleshooting
        _debug: {
          final_url: finalUrl,
          status_code: statusCode,
          crawler_type: 'http-request',
          execution_mode: webhookData.body.execution_mode || 'online',
          timings: {
            fetch_ms: fetchTime,
            render_ms: 0,
            extract_ms: extractTime
          },
          extracted_length: extracted ? extracted.length : 0
        }
      },
      usage: null
    }
  };

return results;

